parameters.functionCode:
const client = $input.first().json;
const now = new Date();
const dueDate = new Date(now.getFullYear(), now.getMonth(), 10);

const invoice = {
  invoiceNumber: `MOOM-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}-${String(Math.floor(Math.random() * 9999)).padStart(4, '0')}`,
  clientName: client.name,
  clientEmail: client.email,
  clientPhone: client.phone,
  plan: client.plan || 'Pro',
  amount: client.monthlyAmount || 4997,
  currency: 'BRL',
  issueDate: now.toISOString().split('T')[0],
  dueDate: dueDate.toISOString().split('T')[0],
  status: 'pendente',
  items: [
    {
      description: `Plano ${client.plan || 'Pro'} - ${now.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })}`,
      quantity: 1,
      unitPrice: client.monthlyAmount || 4997,
      total: client.monthlyAmount || 4997
    }
  ]
};

return [{ json: invoice }];

